    if (two === '<>' || two === '<=' || two === '>=') { t.push({ k: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>():,'.includes(c)) { t.push({ k: 'op', v: c }); i++; continue }
    return null
  }
  return t
}

// returns AST or null
export function parseFormula(body) {
  const t = lex(body)
  if (!t) return null
  let p = 0
  const isOp = v => p < t.length && t[p].k === 'op' && t[p].v === v
  const fail = () => { throw null }
  function cmp() {
    let l = add()
    while (p < t.length && t[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(t[p].v)) {
      const op = t[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = t[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = t[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = t[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= t.length) fail()
    const tk = t[p++]
    if (tk.k === 'num') return { t: 'num', v: tk.v }
    if (tk.k === 'op') {
      if (tk.v === '(') { const e = cmp(); if (!isOp(')')) fail(); p++; return e }
      fail()
    }
    const w = tk.v, U = w.toUpperCase()
