      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return cellVal(n.a)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
