          return { t: 'b', v: res }
        }
        const a = toNum(l); if (a.t === 'e') return a
        const b = toNum(r); if (b.t === 'e') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          case '^': return fin(Math.pow(a.v, b.v))
        }
        return err('#ERR!')
      }
      case 'call': return call(n)
    }
  }
  function call(n) {
    const f = n.name, k = n.args.length
    if (!FUNCS[f]) return err('#NAME?')
    if (f === 'ABS' && k !== 1) return err('#ERR!')
    if (f === 'IF' && k !== 3) return err('#ERR!')
    if (k < 1) return err('#ERR!')
    if (f === 'IF') {
      const cv = argVals(n.args[0])
      if (cv.length !== 1) return cv.find(v => v.t === 'e') || err('#ERR!')
      const c = cv[0]
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      const bv = argVals(n.args[truth ? 1 : 2])
      return bv.length === 1 ? bv[0] : bv.find(v => v.t === 'e') || err('#ERR!')
    }
    const vals = []
    for (const a of n.args) vals.push(...argVals(a))
    const e = vals.find(v => v.t === 'e')
    if (e) return e
    if (f === 'COUNT') return num(vals.filter(v => v.t === 'n').length)
    const ns = []
    for (const v of vals) { const x = toNum(v); if (x.t === 'e') return x; ns.push(x.v) }
    if (f === 'ABS') return ns.length === 1 ? fin(Math.abs(ns[0])) : err('#ERR!')
    if (f === 'SUM') return fin(ns.reduce((a, b) => a + b, 0))
    if (f === 'AVG') return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
    if (f === 'MIN') return fin(ns.reduce((a, b) => (b < a ? b : a)))
    return fin(ns.reduce((a, b) => (b > a ? b : a)))
  }
  return cellVal
}
