import { readFileSync } from 'node:fs'
import { parseAddr, colName, parseFormula, collectDeps, makeEvaluator } from './formula.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const die = m => { process.stderr.write(m + '\n'); process.exit(2) }

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) die('error: usage: cli.js values|deps')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
const list = []
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const addr = m[0]
  let rest = line.slice(addr.length)
  rest = rest.replace(/^[ \t]+/, '')
  const a = parseAddr(addr)
  if (!a) die(`error: line ${i + 1}: invalid cell address ${addr}`)
  if (cells.has(a.key)) die(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  let c
  if (rest[0] === '=') c = { kind: 'f', body: rest.slice(1) }
  else {
    let val
    if (rest === '') val = { t: 'n', v: 0 }
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(rest)) val = { t: 'n', v: Number(rest) }
    else if (ERRS.includes(rest)) val = { t: 'e', v: rest }
    else val = { t: 's', v: rest }
    c = { kind: 'lit', val }
  }
  cells.set(a.key, c)
  list.push({ ...a, c })
})
list.sort((x, y) => x.col - y.col || x.row - y.row)

const out = []
if (mode === 'values') {
  const get = makeEvaluator(cells)
  for (const x of list) {
    const v = get(x)
    let s
    if (v.t === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.t === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${x.key}=${s}`)
  }
} else {
  for (const x of list) {
    let s = x.key + ':'
    if (x.c.kind === 'f') {
      const ast = parseFormula(x.c.body)
      if (ast) {
        const m = new Map()
        collectDeps(ast, m)
        for (const d of [...m.values()].sort((p, q) => p.col - q.col || p.row - q.row)) s += ' ' + colName(d.col) + d.row
      }
    }
    out.push(s)
  }
}
process.stdout.write(out.map(l => l + '\n').join(''))
EOF
