  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = t[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= t.length) fail()
    const tk = t[p++]
    if (tk.k === 'num') return { t: 'num', v: tk.v }
    if (tk.k === 'op') {
      if (tk.v === '(') { const e = cmp(); if (!isOp(')')) fail(); p++; return e }
      fail()
    }
    const w = tk.v, U = w.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { t: 'call', name: U, args }
    }
    if (isOp(':')) {
      p++
      if (p >= t.length || t[p].k !== 'word') fail()
      const w2 = t[p++].v
      if (isOp('(')) fail()
      const bad = x => x.toUpperCase() === 'TRUE' || x.toUpperCase() === 'FALSE'
      if (bad(w) || bad(w2)) fail()
      return { t: 'range', a: parseAddr(w), b: parseAddr(w2) }
    }
    if (U === 'TRUE') return { t: 'bool', v: true }
    if (U === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: parseAddr(w) }
  }
  try {
    const e = cmp()
    if (p !== t.length) return null
    return e
  } catch (e) {
    if (e === null) return null
    throw e
  }
}

export function collectDeps(ast, out) {
  const add = (c, r) => out.set(c * 1000 + r, { col: c, row: r })
  const walk = n => {
    if (n.t === 'ref') { if (n.a) add(n.a.col, n.a.row) }
    else if (n.t === 'range') {
      if (n.a && n.b) rangeCells(n).forEach(([c, r]) => add(c, r))
    } else if (n.t === 'bin') { walk(n.l); walk(n.r) }
    else if (n.t === 'un') walk(n.e)
    else if (n.t === 'call') n.args.forEach(walk)
  }
  walk(ast)
}

export function rangeCells(n) {
  const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
  const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
  const o = []
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) o.push([c, r])
  return o
}

const num = v => ({ t: 'n', v })
const err = v => ({ t: 'e', v })
const ZERO = num(0)

export function makeEvaluator(cells) {
  // cells: Map key -> {kind:'lit', val} | {kind:'f', body}
  const memo = new Map()
  const busy = new Set()
  function cellVal(a) {
    if (!a) return err('#REF!')
    const c = cells.get(a.key)
    if (!c) return ZERO
    if (c.kind === 'lit') return c.val
    if (memo.has(a.key)) return memo.get(a.key)
    if (busy.has(a.key)) return err('#CYCLE!')
    busy.add(a.key)
    const ast = parseFormula(c.body)
    const v = ast ? ev(ast) : err('#ERR!')
    busy.delete(a.key)
    memo.set(a.key, v)
    return v
  }
  function toNum(v) {
    if (v.t === 'e') return v
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }
  const fin = x => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
  const rank = v => (v.t === 'n' ? 0 : v.t === 's' ? 1 : 2)
  function compare(a, b) {
    const ra = rank(a), rb = rank(b)
    if (ra !== rb) return ra < rb ? -1 : 1
    if (ra === 2) return (a.v ? 1 : 0) - (b.v ? 1 : 0)
    if (ra === 0) return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d < 0 ? -1 : 1
    }
    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
  }
  // expand args into list of values (single list), or error
  function argVals(arg) {
    if (arg.t === 'range') {
      if (!arg.a || !arg.b) return [err('#REF!')]
      return rangeCells(arg).map(([c, r]) => cellVal({ key: colName(c) + r }))
    }
    return [ev(arg)]
  }
  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return cellVal(n.a)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
        if (l.t === 'e') return l
        if (r.t === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'b', v: res }
        }
        const a = toNum(l); if (a.t === 'e') return a
        const b = toNum(r); if (b.t === 'e') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          case '^': return fin(Math.pow(a.v, b.v))
        }
        return err('#ERR!')
      }
      case 'call': return call(n)
    }
  }
  function call(n) {
    const f = n.name, k = n.args.length
    if (!FUNCS[f]) return err('#NAME?')
    if (f === 'ABS' && k !== 1) return err('#ERR!')
    if (f === 'IF' && k !== 3) return err('#ERR!')
    if (k < 1) return err('#ERR!')
    if (f === 'IF') {
      const cv = argVals(n.args[0])
      if (cv.length !== 1) return cv.find(v => v.t === 'e') || err('#ERR!')
      const c = cv[0]
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      const bv = argVals(n.args[truth ? 1 : 2])
      return bv.length === 1 ? bv[0] : bv.find(v => v.t === 'e') || err('#ERR!')
    }
    const vals = []
    for (const a of n.args) vals.push(...argVals(a))
    const e = vals.find(v => v.t === 'e')
    if (e) return e
    if (f === 'COUNT') return num(vals.filter(v => v.t === 'n').length)
    const ns = []
    for (const v of vals) { const x = toNum(v); if (x.t === 'e') return x; ns.push(x.v) }
    if (f === 'ABS') return ns.length === 1 ? fin(Math.abs(ns[0])) : err('#ERR!')
    if (f === 'SUM') return fin(ns.reduce((a, b) => a + b, 0))
    if (f === 'AVG') return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
    if (f === 'MIN') return fin(ns.reduce((a, b) => (b < a ? b : a)))
    return fin(ns.reduce((a, b) => (b > a ? b : a)))
  }
  return cellVal
}
